<template>
  <div class="hm-card">

    <div class="hm-header">
      <div class="hm-tag">{{ $t('supProd.tag') }}</div>
      <h2 class="hm-title">{{ chartTitle || $t('supProd.managerTitle') }}</h2>
      <p class="hm-sub">{{ period }}</p>
    </div>

    <div class="hm-wrap">
      <table class="hm-table">
        <thead>
          <tr>
            <th class="hm-th hm-th--store"></th>
            <th
                v-for="m in METRICS"
                :key="m.key"
                class="hm-th"
                :style="{ color: m.color }"
            >
              <span class="hm-metric-icon">{{ m.icon }}</span>
              {{ $t(m.labelKey) }}
            </th>
          </tr>
        </thead>
        <tbody>
          <tr v-for="item in items" :key="item.name" class="hm-row">
            <td class="hm-td hm-td--store">{{ item.name }}</td>
            <td
                v-for="m in METRICS"
                :key="m.key"
                class="hm-td hm-td--cell"
            >
              <div
                  class="hm-cell"
                  :style="{
                    background: cellBg(item[m.key], m.key, m.color),
                    color: cellTextColor(item[m.key], m.key),
                  }"
              >
                {{ fmt(item[m.key]) }}%
              </div>
            </td>
          </tr>
        </tbody>
      </table>
    </div>

    <!-- Легенда -->
    <div class="hm-legend">
      <span class="hm-legend-label">{{ $t('supProd.belowAvg') }}</span>
      <div class="hm-legend-gradient"></div>
      <span class="hm-legend-label">{{ $t('supProd.aboveAvg') }}</span>
    </div>

  </div>
</template>

<script>
const METRICS = [
  { key: 'smart',    labelKey: 'supProd.smart',   icon: '📱', color: '#6366f1' },
  { key: 'note',     labelKey: 'supProd.note',     icon: '💻', color: '#f59e0b' },
  { key: 'tv',       labelKey: 'supProd.tv',       icon: '📺', color: '#14b8a6' },
  { key: 'sup_prod', labelKey: 'supProd.supProd',  icon: '🛍️', color: '#22c55e' },
  { key: 'poslug',   labelKey: 'supProd.poslug',   icon: '🛡️', color: '#ec4899' },
]

export default {
  name: 'SupProdHeatmap',

  props: {
    items:      { type: Array,  default: () => [] },
    chartTitle: { type: String, default: '' },
    period:     { type: String, default: '' },
  },

  data() {
    return { METRICS }
  },

  computed: {
    // Максимум по каждой колонке для нормализации цвета
    colMaxes() {
      const result = {}
      METRICS.forEach(m => {
        result[m.key] = Math.max(...this.items.map(i => Number(i[m.key] ?? 0)), 0.01)
      })
      return result
    },
  },

  methods: {
    fmt(val) {
      const n = Number(val ?? 0)
      return n.toFixed(1).replace('.', ',')
    },

    // Нормализованное значение 0..1 относительно max колонки
    norm(val, key) {
      const max = this.colMaxes[key] || 1
      return Math.min(Number(val ?? 0) / max, 1)
    },

    // Фон ячейки: цвет метрики с прозрачностью пропорциональной значению
    cellBg(val, key, color) {
      const t = this.norm(val, key)
      if (t < 0.01) return '#f8fafc'
      // Плавный градиент от почти белого до насыщенного цвета
      const opacity = 0.08 + t * 0.72  // 0.08 → 0.80
      return this.hexToRgba(color, opacity)
    },

    // Цвет текста: тёмный на светлом фоне, белый на тёмном
    cellTextColor(val, key) {
      const t = this.norm(val, key)
      return t > 0.6 ? '#ffffff' : '#1e293b'
    },

    hexToRgba(hex, alpha) {
      const r = parseInt(hex.slice(1, 3), 16)
      const g = parseInt(hex.slice(3, 5), 16)
      const b = parseInt(hex.slice(5, 7), 16)
      return `rgba(${r},${g},${b},${alpha})`
    },
  },
}
</script>

